import { isAbsolute, join, normalize } from "../../../platform/compat/path/index.js";
import { rendererLogger } from "../../../utils/index.js";
import { COMPONENT_ERROR, CONFIG_INVALID } from "../../../errors/index.js";
import { isPathContainedBy } from "../../../platform/adapters/path-containment.js";
import { isCanonicalNotFoundError } from "../../../platform/compat/not-found-error.js";
const logger = rendererLogger.component("app-resolver");
const VALID_EXTENSIONS = ["tsx", "jsx", "ts", "js", "mdx", "md"];
function isValidComponentPath(path) {
    const ext = path.slice(path.lastIndexOf(".") + 1);
    return VALID_EXTENSIONS.includes(ext);
}
async function assertCanonicalContainment(path, projectRoot, displayPath, adapter) {
    const realPath = adapter.fs.realPath;
    if (!realPath)
        return;
    let canonicalRoot;
    let canonicalPath;
    try {
        [canonicalRoot, canonicalPath] = await Promise.all([
            realPath.call(adapter.fs, projectRoot),
            realPath.call(adapter.fs, path),
        ]);
    }
    catch (error) {
        if (isCanonicalNotFoundError(error)) {
            throw CONFIG_INVALID.create({
                detail: `Configured app component does not exist: "${displayPath}". Check your veryfront.config.ts 'app' setting.`,
            });
        }
        throw COMPONENT_ERROR.create({
            detail: "App component path could not be resolved",
            cause: error,
            context: { component: "app", phase: "server" },
        });
    }
    if (!isPathContainedBy(canonicalPath, canonicalRoot)) {
        throw CONFIG_INVALID.create({
            detail: `Configured app component resolves outside the project directory: "${displayPath}". Check your veryfront.config.ts 'app' setting.`,
        });
    }
}
export async function resolveAppComponentPath(projectDir, adapter, config) {
    logger.debug("Starting resolution", {
        projectDir,
        hasAdapter: !!adapter,
        hasConfig: !!config,
        configApp: config?.app,
    });
    const configApp = config?.app;
    if (configApp === false) {
        logger.debug("App component disabled via config.app: false");
        return null;
    }
    if (configApp) {
        const displayPath = isAbsolute(configApp) ? "<absolute path>" : configApp;
        if (!isValidComponentPath(configApp)) {
            throw CONFIG_INVALID.create({
                detail: `Invalid app component path: "${displayPath}". Check your veryfront.config.ts 'app' setting.`,
            });
        }
        const projectRoot = normalize(projectDir);
        const appPath = isAbsolute(configApp)
            ? normalize(configApp)
            : normalize(join(projectRoot, configApp));
        if (!isPathContainedBy(appPath, projectRoot)) {
            throw CONFIG_INVALID.create({
                detail: `Configured app component must stay inside the project directory: "${displayPath}". Check your veryfront.config.ts 'app' setting.`,
            });
        }
        if (!(await adapter.fs.exists(appPath))) {
            throw CONFIG_INVALID.create({
                detail: `Configured app component does not exist: "${displayPath}". Check your veryfront.config.ts 'app' setting.`,
            });
        }
        await assertCanonicalContainment(appPath, projectRoot, displayPath, adapter);
        logger.debug("Using config.app", { path: appPath });
        return appPath;
    }
    for (const ext of VALID_EXTENSIONS) {
        const appPath = join(projectDir, `components/app.${ext}`);
        const exists = await adapter.fs.exists(appPath);
        logger.debug("Checking default path", { appPath, exists });
        if (!exists)
            continue;
        await assertCanonicalContainment(appPath, normalize(projectDir), `components/app.${ext}`, adapter);
        logger.debug("Found app component via discovery", { path: appPath });
        return appPath;
    }
    logger.debug("No app component found");
    return null;
}
